insert into public.works (id, category, slug, title, client, year, summary, description, cover_url, gallery, video_url, tags, created_at) values ('00000000-0000-4000-8000-000000000001', 'branding', 'meridian-studio', 'Meridian Studio', 'Meridian Studio', '2025', 'A calm, architectural identity for an independent design studio.', 'A calm, architectural identity for an independent design studio. The brief called for a system that could flex from a favicon to a billboard without losing its voice. We started with research and positioning, explored three distinct directions, then refined one into a complete toolkit: mark, typography, colour, layout rules and motion principles.', '/works/work-2.jpg', array['/works/work-2.jpg']::text[], null, array['Identity','Print']::text[], '2025-01-01T00:00:00.000Z') on conflict do nothing;
