insert into public.reviews (id, work_id, name, position, rating, message, created_at) values ('00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000004', 'Ilana Rowe', 'CEO, Sartfaure', 5, 'Nabeel doesn''t just design — he thinks. He reframed our entire brand in a way that finally felt like us.', '2025-03-01') on conflict do nothing;
insert into public.reviews (id, work_id, name, position, rating, message, created_at) values ('00000000-0000-4000-8000-000000000002', '00000000-0000-4000-8000-000000000002', 'Marcus Field', 'Founder, Nova Ledger', 5, 'A rare combination of taste, strategy and craft. Every deliverable felt three levels beyond what we asked for.', '2025-02-01') on conflict do nothing;
insert into public.reviews (id, work_id, name, position, rating, message, created_at) values ('00000000-0000-4000-8000-000000000003', '00000000-0000-4000-8000-000000000005', 'Priya Menon', 'Creative Lead, Orbit Co.', 5, 'The identity system he built for us still holds up two years later. That''s the real test.', '2025-01-01') on conflict do nothing;
