insert into public.reviews (id, work_id, name, position, rating, message, created_at) values ('00000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000000003', 'Lena Voss', 'Director, Suiss Type Foundry', 5, 'Rare taste, rarer discipline. Nabeel treats a wordmark like a piece of architecture — every proportion earned.', '2024-11-01') on conflict do nothing;
insert into public.reviews (id, work_id, name, position, rating, message, created_at) values ('00000000-0000-4000-8000-000000000006', '00000000-0000-4000-8000-000000000006', 'Kai Rhen', 'Founder, Halo Wear', 5, 'He gave a small label the visual language of a house ten times its size — without a single hollow gesture.', '2024-10-01') on conflict do nothing;
